G=load()

def f(inp):
    g=[r[:] for r in inp]; h=len(g); w=len(g[0])
    def line_density(cells): return sum(c==2 for c in cells)/len(cells)
    hlines=[i for i in range(h) if line_density([g[i][j] for j in range(w)])>=0.8]
    vlines=[j for j in range(w) if line_density([g[i][j] for i in range(h)])>=0.8]
    markers=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==2 and i not in hlines and j not in vlines:
                markers.append((i,j))
    out=[r[:] for r in g]
    def paint(i,j):
        if 0<=i<h and 0<=j<w:
            if out[i][j] in (0,2): out[i][j]=1
    for (mi,mj) in markers:
        onv = mj in vlines; onh = mi in hlines
        # paint along both axes, skipping 3s and marker cell
        for j in range(w):
            if out[mi][j]!=3: paint(mi,j)
        for i in range(h):
            if out[i][mj]!=3: paint(i,mj)
        # rings: for each existing line crossing a painted full line, ring around crossing point
        crossings=[]
        if onv:
            for li in hlines: crossings.append((mi-li*1 or 0,mj,li,'h'))
        else:
            pass
        # handle: painted row crosses vlines; painted col crosses hlines
        if not onv:   # painted row mi; crossings with vlines
            for lj in vlines:
                if lj!=mj:
                    for di in (-1,0,1):
                        for dj in (-1,0,1):
                            ii,ii_ = mi+di, lj+dj
                            if 0<=ii<h and 0<=ii_<w and out[ii][ii_] in (0,2): out[ii][ii_]=1
        if not onh:   # painted col mj; crossings with hlines
            for li in hlines:
                if li!=mi:
                    for di in (-1,0,1):
                        for dj in (-1,0,1):
                            ii,ij = li+di, mj+dj
                            if 0<=ii<h and 0<=ij<w and out[ii][ij] in (0,2): out[ii][ij]=1
        if onv and onh:
            for di in (-1,0,1):
                for dj in (-1,0,1):
                    ii,ij=mi+di,mj+dj
                    if 0<=ii<h and 0<=ij<w and out[ii][ij] in (0,2): out[ii][ij]=1
    return out

