def f(inp):
    g=[r[:] for r in inp]; h=len(g); w=len(g[0])
    out=[r[:] for r in g]
    markers=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==2 and all(0<=i+di<h and 0<=j+dj<w and g[i+di][j+dj]==3 for di,dj in [(-1,-1),(-1,1),(1,-1),(1,1)]):
                markers.append((i,j))
    def runs(values):
        res=[]; cur=[]
        for v in values:
            if v==2: cur.append(v)
            else:
                if len(cur)>=1: res.append(len(cur)); cur=[]
        if cur: res.append(len(cur))
        return res
    def axis_runs(i,j,ax):
        # runs of 2s along axis ax passing near marker (both directions)
        vals=g[i:] if ax==0 else None
        if ax==0:  # horizontal: scan row i left/right
            L=[g[i][j-k] for k in range(j,-1,-1)]
            R=[g[i][j+k] for k in range(1,w-j)]
            return runs(L[::-1]), runs(R)
        else:
            U=[g[k][j] for k in range(i,-1,-1)]
            D=[g[k][j] for k in range(i+1,h)]
            return runs(U[::-1]), runs(D)
    for (mi,mj) in markers:
        hr,hr_=axis_runs(mi,mj,0)
        vc,vc_=axis_runs(mi,mj,1)
        # choose orientation: axis with runs on both sides (min run>=1), preferring longer total
        cand={}
        if hr[0]>=1 and hr_[0]>=1: cand['row']=sum(hr)+sum(hr_)
        if vc[0]>=1 and vc_[0]>=1: cand['col']=sum(vc)+sum(vc_)
        orient=cand[max(cand,key=cand.get)] if cand else 'row'
        perp = 'col' if orient=='row' else 'row'
        if perp=='col':
            for jj in range(w):
                if out[mi][jj]==0: out[mi][jj]=1
        else:
            for ii in range(h):
                if out[ii][mj]==0: out[ii][mj]=1
        # ring around each crossing: 2s on painted axis forming a run>=2 in perpendicular orientation
        pts=[]
        if perp=='col':
            for jj in range(w):
                if g[mi][jj]==2 and any(g[mi-k][jj]==2 for k in range(1,max(1,jj+1))) and any(g[mi+k][jj]==2 for k in range(1,h-mi)):
                    pts.append((mi,jj))
        else:
            for ii in range(h):
                if g[ii][mj]==2 and any(g[ii][mj-k]==2 for k in range(1,mj+1)) and any(g[ii][mj+k]==2 for k in range(1,w-mj)):
                    pts.append((ii,mj))
        for (ci,cj) in pts:
            for di in (-1,0,1):
                for dj in (-1,0,1):
                    if 0<=ci+di<h and 0<=cj+dj<w and out[ci+di][cj+dj] in (0,2):
                        out[ci+di][cj+dj]=1
    return out

